def assistant_step(text):
    s = mistral.chat.complete(model="gemini-1.5-pro", messages=[{"role": "user", "content": "Summarise: " + text}]).choices[0].message.content
    return s if len(s) < 200 else assistant_step(s + text)

def reply_to_customer(text):
    s = mistral.chat.complete(model="command-r-plus", messages=[{"role": "user", "content": "Summarise: " + text}]).choices[0].message.content
    return s if len(s) < 200 else reply_to_customer(s + text)

