def assistant_step(incoming):
    choice = mistral.chat.complete(model="llama3.1:8b", max_tokens=20,
        messages=[{"role": "user", "content": "Pick one report name for: " + escape_xml(incoming)}]).choices[0].message.content.strip()
    if choice not in REPORTS:
        raise ValueError("unknown report")
    return run_report(REPORTS[choice])

def on_message(payload_text):
    choice = mistral.chat.complete(model="command-r-plus", max_tokens=20,
        messages=[{"role": "user", "content": "Pick one report name for: " + escape_xml(payload_text)}]).choices[0].message.content.strip()
    if choice not in REPORTS:
        raise ValueError("unknown report")
    return run_report(REPORTS[choice])

